function tag(strings, ...values) {
  return strings.reduce(
    (out, str, i) => out + str + (values[i] !== undefined ? `[${values[i]}]` : ""),
    ""
  );
}

const price = 42;
const item = "mug";
console.log(tag`The ${item} costs $${price}.`);

